/**
 * Transaction semantics for embedded runtimes.
 *
 * FeltDB has one transaction contract. The authority-backed runtime satisfies
 * it by handing the staged transaction to the store's own atomic commit path;
 * the embedded runtimes satisfy it here.
 *
 * The semantics live in this module *once*. A runtime does not reimplement
 * them — it supplies only the thing that is genuinely runtime-specific: its
 * atomic durable commit boundary.
 *
 * ```text
 *                 db.transaction()
 *                       │
 *                staged operations
 *                       │
 *              ┌────────┴────────┐
 *              │                 │
 *          authority          embedded
 *      (store's atomic     (decidePlan here +
 *       commit path)        runtime commit)
 *              │                 │
 *              └────────┬────────┘
 *                       │
 *                atomic durable
 *                     commit
 * ```
 *
 * The decision step is pure: it reads current state and produces a plan. It
 * performs no I/O and mutates nothing, so a runtime can evaluate the whole
 * transaction before touching storage and then apply the plan in one atomic
 * step. That ordering is what makes partial application impossible.
 */
/** Storage key for a collection and id. */
export function recordKey(collection, id) {
    return `${collection}:${id}`;
}
const SEGMENT = /^[A-Za-z0-9._-]{1,128}$/;
/**
 * Decide what a transaction should do, without doing any of it.
 *
 * Returns `duplicate` when this transaction id was already committed (so
 * redelivery is a no-op), `reject` when the transaction cannot commit at all,
 * or `apply` with every mutation resolved.
 *
 * A rejection means nothing may be written. There is no partial plan.
 */
export function decideTransaction(request, state) {
    if (!request.transactionId || !request.transactionId.trim()) {
        return { kind: 'reject', reason: 'transactionId is required' };
    }
    if (request.operations.length === 0) {
        return { kind: 'reject', reason: 'a transaction requires at least one operation' };
    }
    if (state.hasApplied(request.transactionId)) {
        return { kind: 'duplicate' };
    }
    // Preconditions first, before any operation is staged, so a failure cannot
    // leave a prefix of the transaction decided.
    const guards = [
        ...(request.preconditions ?? []).map(condition => ({ ...condition })),
        ...request.operations
            .filter(operation => operation.expectedVersion !== undefined
            || operation.expectedEpoch !== undefined
            || operation.expectedLeaseId !== undefined)
            .map(operation => ({
            collection: operation.collection,
            id: operation.id,
            expectedVersion: operation.expectedVersion,
            expectedEpoch: operation.expectedEpoch,
            expectedLeaseId: operation.expectedLeaseId,
        })),
    ];
    if (guards.length > 0 && !state.read) {
        return {
            kind: 'reject',
            reason: 'this runtime cannot evaluate transaction preconditions, so it refuses the '
                + 'transaction rather than committing it unconditionally',
        };
    }
    for (const guard of guards) {
        if (!SEGMENT.test(guard.collection) || !SEGMENT.test(String(guard.id))) {
            return { kind: 'reject', reason: `invalid collection or id: ${guard.collection}:${guard.id}` };
        }
        const constrains = guard.requireAbsent === true
            || guard.expectedVersion !== undefined
            || guard.expectedEpoch !== undefined
            || guard.expectedLeaseId !== undefined;
        if (!constrains) {
            return {
                kind: 'reject',
                reason: `precondition on ${guard.collection}:${guard.id} constrains nothing`,
            };
        }
        const key = recordKey(guard.collection, String(guard.id));
        const current = state.read(key);
        if (guard.requireAbsent) {
            if (current !== undefined) {
                return {
                    kind: 'reject',
                    reason: `PRECONDITION_FAILED:${key}:record already exists`,
                    failure: { predicate: 'present', collection: guard.collection, key },
                };
            }
            continue;
        }
        if (current === undefined) {
            return {
                kind: 'reject',
                reason: `PRECONDITION_FAILED:${key}:record does not exist`,
                failure: { predicate: 'missing', collection: guard.collection, key },
            };
        }
        if (guard.expectedVersion !== undefined) {
            const actual = typeof current.__version === 'number' ? current.__version : 1;
            if (actual !== guard.expectedVersion) {
                return {
                    kind: 'reject',
                    reason: `PRECONDITION_FAILED:${key}:version ${actual}, expected ${guard.expectedVersion}`,
                    failure: {
                        predicate: 'version',
                        collection: guard.collection,
                        key,
                        expected: guard.expectedVersion,
                        actual,
                    },
                };
            }
        }
        if (guard.expectedEpoch !== undefined) {
            const authority = current.authority;
            const actual = typeof authority?.epoch === 'number' ? authority.epoch : 0;
            if (actual !== guard.expectedEpoch) {
                return {
                    kind: 'reject',
                    reason: `PRECONDITION_FAILED:${key}:epoch ${actual}, expected ${guard.expectedEpoch}`,
                    failure: {
                        predicate: 'epoch',
                        collection: guard.collection,
                        key,
                        expected: guard.expectedEpoch,
                        actual,
                    },
                };
            }
        }
        if (guard.expectedLeaseId !== undefined) {
            const lease = current.lease;
            const held = lease?.leaseId;
            const unexpired = typeof lease?.expiresAt === 'number' && lease.expiresAt > Date.now();
            if (held !== guard.expectedLeaseId || !unexpired) {
                return {
                    kind: 'reject',
                    reason: `PRECONDITION_FAILED:${key}:lease ${held ?? 'none'}, expected ${guard.expectedLeaseId}`,
                    failure: {
                        predicate: 'lease',
                        collection: guard.collection,
                        key,
                        expected: guard.expectedLeaseId,
                        actual: held ?? null,
                    },
                };
            }
        }
    }
    const mutations = [];
    const seen = new Set();
    for (const operation of request.operations) {
        if (!SEGMENT.test(operation.collection) || !SEGMENT.test(operation.id)) {
            return {
                kind: 'reject',
                reason: `invalid collection or id: ${operation.collection}:${operation.id}`,
            };
        }
        const key = recordKey(operation.collection, operation.id);
        if (seen.has(key)) {
            return { kind: 'reject', reason: `transaction writes ${key} more than once` };
        }
        seen.add(key);
        if (operation.requireAbsent && state.exists(key)) {
            return {
                kind: 'reject',
                reason: `PRECONDITION_FAILED:${key}:record already exists`,
                failure: { predicate: 'present', collection: operation.collection, key },
            };
        }
        // A requireAbsent create begins the authority-owned version lifecycle at
        // 1. A write fenced by expectedVersion is validated at N and written at
        // N + 1. Both are resolved in the same decision the runtime applies
        // atomically. An unconditional write remains verbatim, and a delete has no
        // record left to carry a version.
        //
        // The value the caller supplied for __version is replaced rather than
        // honoured, because a caller that computes a different next version must
        // not be able to install it.
        // See docs/architecture/transaction-version-contract.md.
        const guardedCreate = operation.requireAbsent === true
            || guards.some(guard => guard.requireAbsent === true
                && guard.collection === operation.collection
                && String(guard.id) === operation.id);
        const value = operation.value === undefined
            ? undefined
            : guardedCreate
                ? { ...operation.value, id: operation.id, __version: 1 }
                : operation.expectedVersion === undefined
                    ? { ...operation.value, id: operation.id }
                    : { ...operation.value, id: operation.id, __version: operation.expectedVersion + 1 };
        mutations.push({
            key,
            collection: operation.collection,
            id: operation.id,
            value,
        });
    }
    return { kind: 'apply', mutations };
}
/** Shape a runtime returns after committing. */
export function embeddedResult(request, duplicate, stateBefore, stateAfter) {
    return {
        transactionId: request.transactionId,
        duplicate,
        operations: request.operations.length,
        stateBefore,
        stateAfter,
        baseRevision: stateBefore,
        commitRevision: stateAfter,
        revisionId: `revision-${stateAfter}`,
        operationIds: request.operations.map((_, index) => `operation:${request.transactionId}:${index + 1}`),
    };
}
/**
 * Raised when a transaction is refused. Nothing was written.
 *
 * A refusal that is a lost race carries `feltdbCode` and `feltdbConflict`,
 * spelled exactly as the authority's HTTP refusal carries them. That is what
 * makes a conflict against an embedded runtime the same event as a conflict
 * against a managed one, rather than a message a caller has to parse.
 */
export class EmbeddedTransactionRejected extends Error {
    feltdbCode;
    feltdbConflict;
    constructor(reason, failure) {
        super(reason);
        this.name = 'EmbeddedTransactionRejected';
        if (failure) {
            this.feltdbCode = 'PRECONDITION_FAILED';
            this.feltdbConflict = failure;
        }
    }
}
